items.solution:
const SIMPLE_HEADERS = ['accept', 'accept-language', 'content-language', 'content-type'];
const SIMPLE_CONTENT_TYPES = ['application/x-www-form-urlencoded', 'multipart/form-data', 'text/plain'];
const SIMPLE_METHODS = ['GET', 'HEAD', 'POST'];

function needsPreflight(method, headers = {}) {
  if (!SIMPLE_METHODS.includes(method.toUpperCase())) return true;
  for (const key of Object.keys(headers)) {
    if (!SIMPLE_HEADERS.includes(key.toLowerCase())) return true;
  }
  if (headers['Content-Type'] && !SIMPLE_CONTENT_TYPES.includes(headers['Content-Type'])) {
    return true;
  }
  return false;
}

